"""Streaming Deepgram Flux text-to-speech integration.

Protocol reference: https://developers.deepgram.com/reference/text-to-speech/speak-flux
"""

from __future__ import annotations

import os
from typing import AsyncIterator, Dict, List, Literal, Optional
from urllib.parse import urlencode

import aiohttp
import orjson
import structlog
from aiohttp import ClientTimeout, ClientWSTimeout, WSMsgType
from pydantic import field_validator, model_validator

from rasa.core.channels.voice_stream.audio_bytes import (
    L16_16KHZ,
    L16_24KHZ,
    L16_48KHZ,
    MULAW_8KHZ,
    AudioFormat,
    RasaAudioBytes,
)
from rasa.core.channels.voice_stream.tts._client_session import (
    create_ssl_client_session,
)
from rasa.core.channels.voice_stream.tts.tts_engine import (
    TTSEngine,
    TTSEngineConfig,
    TTSError,
    TTSLanguageMapEntry,
)
from rasa.shared.constants import DEEPGRAM_API_KEY_ENV_VAR
from rasa.tracing import voice as voice_tracing

logger = structlog.get_logger(__name__)


class DeepgramFluxTTSConfig(TTSEngineConfig):
    """Connection-level configuration for Deepgram Flux TTS."""

    endpoint: str = "wss://api.deepgram.com/v2/speak"
    speed: Optional[float] = None
    expressivity: Literal[-2, -1, 0, 1, 2] = 0
    mip_opt_out: bool = False
    tag: Optional[str] = None

    @field_validator("speed")
    @classmethod
    def validate_speed(cls, speed: Optional[float]) -> Optional[float]:
        if speed is None:
            return speed

        speed_step = speed * 20
        is_supported_increment = abs(round(speed_step) - speed_step) < 1e-9
        if not 0.5 <= speed <= 1.5 or not is_supported_increment:
            raise ValueError(f"Unsupported Deepgram Flux speed: {speed}")
        return speed

    @model_validator(mode="after")
    def validate_flux_settings(self) -> "DeepgramFluxTTSConfig":
        if not self.endpoint.startswith("wss://"):
            raise ValueError("Deepgram Flux endpoint must use wss://")
        if self.language_map:
            for language, entry in self.language_map.items():
                if entry.model is None or not entry.model.startswith("flux-"):
                    raise ValueError(
                        "Deepgram Flux language_map entry "
                        f"'{language}' requires a model starting with 'flux-'"
                    )
        return self

    def apply_deprecated_fields(self, rasa_language: str) -> "DeepgramFluxTTSConfig":
        config = super().apply_deprecated_fields(rasa_language)
        return self.__class__.model_validate(config.model_dump())


class DeepgramFluxTTS(TTSEngine[DeepgramFluxTTSConfig]):
    """Turn-based, streaming-input TTS engine for Deepgram Flux."""

    required_env_vars = (DEEPGRAM_API_KEY_ENV_VAR,)
    streaming_input = True

    def __init__(
        self,
        rasa_language: str,
        format: AudioFormat,
        config: Optional[DeepgramFluxTTSConfig] = None,
        additional_languages: Optional[List[str]] = None,
    ) -> None:
        super().__init__(rasa_language, format, config, additional_languages)
        self.session: Optional[aiohttp.ClientSession] = None
        self.ws: Optional[aiohttp.ClientWebSocketResponse] = None

    @classmethod
    def name(cls) -> str:
        return "deepgram_flux"

    @staticmethod
    def get_request_headers(config: DeepgramFluxTTSConfig) -> Dict[str, str]:
        return {
            "Authorization": f"Token {os.environ[DEEPGRAM_API_KEY_ENV_VAR]}",
        }

    def get_websocket_url(self, config: DeepgramFluxTTSConfig) -> str:
        if self.audio_format in (L16_16KHZ, L16_24KHZ, L16_48KHZ):
            encoding = "linear16"
        elif self.audio_format == MULAW_8KHZ:
            encoding = "mulaw"
        else:
            raise TTSError(
                f"Unsupported audio format {self.audio_format} for Deepgram Flux TTS"
            )

        query_params: Dict[str, object] = {
            "model": self.current_language_config.model,
            "encoding": encoding,
            "sample_rate": self.audio_format.sample_rate,
            "expressivity": config.expressivity,
            "mip_opt_out": str(config.mip_opt_out).lower(),
        }
        if config.speed is not None:
            query_params["speed"] = f"{config.speed:.2f}"
        if config.tag is not None:
            query_params["tag"] = config.tag
        return f"{config.endpoint}?{urlencode(query_params)}"

    @voice_tracing.traced_tts_connect
    async def connect(self, config: Optional[DeepgramFluxTTSConfig] = None) -> None:
        if self.ws is not None and not self.ws.closed:
            return

        try:
            if self.session is not None and not self.session.closed:
                await self.session.close()
            timeout = ClientTimeout(
                total=None,
                sock_connect=float(self.config.timeout),
            )
            self.session = create_ssl_client_session(timeout)
            self.ws = await self.session.ws_connect(
                self.get_websocket_url(self.config),
                headers=self.get_request_headers(self.config),
                timeout=ClientWSTimeout(ws_close=float(self.config.timeout)),
                heartbeat=30.0,
            )
        except (aiohttp.ClientError, TimeoutError) as error:
            if self.session is not None and not self.session.closed:
                await self.session.close()
            self.session = None
            self.ws = None
            raise TTSError(
                f"Could not connect to Deepgram Flux TTS: {error}"
            ) from error

    @voice_tracing.traced_tts_disconnect
    async def close_connection(self) -> None:
        """Close the Flux socket and its HTTP session."""
        ws = self.ws
        session = self.session
        self.ws = None
        self.session = None

        try:
            if ws is not None and not ws.closed:
                await ws.close()
        finally:
            if session is not None and not session.closed:
                await session.close()

    async def _send_message(self, message: Dict[str, object]) -> None:
        async with self._get_engine_lock():
            if self.ws is None or self.ws.closed:
                raise TTSError("Deepgram Flux WebSocket connection is not established")
            try:
                await self.ws.send_json(message)
            except (aiohttp.ClientError, RuntimeError) as error:
                raise TTSError(
                    f"Could not send data to Deepgram Flux TTS: {error}"
                ) from error

    async def send_text_chunk(self, text: str) -> None:
        await self._send_message({"type": "Speak", "text": text})

    async def signal_text_done(self) -> None:
        await self._send_message({"type": "Flush"})

    async def signal_interrupt(self) -> None:
        """Request interruption of the active Flux turn."""
        await self._send_message({"type": "Interrupt"})
        logger.debug("deepgram_flux.tts.interrupt")

    async def stream_audio(self) -> AsyncIterator[RasaAudioBytes]:
        if self.ws is None or self.ws.closed:
            raise TTSError("Deepgram Flux WebSocket connection is not established")

        try:
            async for message in self.ws:
                if message.type == WSMsgType.BINARY:
                    yield self.engine_bytes_to_rasa_audio_bytes(message.data)
                    continue

                if message.type == WSMsgType.TEXT:
                    payload = orjson.loads(message.data)
                    if not isinstance(payload, dict):
                        raise TTSError(
                            "Deepgram Flux returned an invalid control message"
                        )
                    message_type = payload.get("type")

                    if message_type in {
                        "SpeechMetadata",
                        "SpeechInterrupted",
                        "SessionMetadata",
                    }:
                        logger.debug(
                            "deepgram_flux.stream_audio.complete",
                            message_type=message_type,
                        )
                        return
                    if message_type == "Error":
                        code = payload.get("code", "unknown")
                        description = payload.get("description", "Unknown error")
                        raise TTSError(f"Deepgram Flux TTS error {code}: {description}")
                    if message_type in {"Warning", "ConfigureFailure"}:
                        logger.warning(
                            "deepgram_flux.stream_audio.provider_warning",
                            message_type=message_type,
                            code=payload.get("code"),
                            description=payload.get("description"),
                        )
                        if payload.get("code") == "NO_AUDIO_GENERATED":
                            return
                    continue

                if message.type in {
                    WSMsgType.CLOSE,
                    WSMsgType.CLOSED,
                    WSMsgType.CLOSING,
                }:
                    return
                if message.type == WSMsgType.ERROR:
                    raise TTSError(f"Deepgram Flux WebSocket error: {message.data}")
        except TTSError:
            raise
        except (aiohttp.ClientError, orjson.JSONDecodeError, TypeError) as error:
            logger.error("deepgram_flux.stream_audio.error", error=str(error))
            raise TTSError(
                f"Error while streaming Deepgram Flux audio: {error}"
            ) from error

    async def synthesize(
        self,
        text: str,
        config: Optional[DeepgramFluxTTSConfig] = None,
    ) -> AsyncIterator[RasaAudioBytes]:
        await self.send_text_chunk(text)
        await self.signal_text_done()
        async for audio_chunk in self.stream_audio():
            yield audio_chunk

    def engine_bytes_to_rasa_audio_bytes(self, chunk: bytes) -> RasaAudioBytes:
        return RasaAudioBytes(chunk, format=self.audio_format)

    @staticmethod
    def get_default_config(rasa_language: str) -> DeepgramFluxTTSConfig:
        return DeepgramFluxTTSConfig(
            language_map={
                rasa_language: TTSLanguageMapEntry(model="flux-alexis-en"),
            }
        )

    @classmethod
    def from_config_dict(
        cls,
        config: Dict[str, object],
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> "DeepgramFluxTTS":
        return cls(
            rasa_language=rasa_language,
            format=format,
            config=DeepgramFluxTTSConfig.model_validate(config),
            additional_languages=additional_languages,
        )

    async def set_language(self, rasa_language: str) -> bool:
        if not await super().set_language(rasa_language):
            return False
        await self._reconnect_with_lock()
        return True
